1	import { test } from 'node:test';
2	import assert from 'node:assert/strict';
3	import { listOrdersForUser, totalPaidCents } from '../src/services/order-service.js';
4	
5	test('listOrdersForUser returns only that user orders', (t, done) => {
6	  listOrdersForUser(1, (err, orders) => {
7	    assert.equal(err, null);
8	    assert.equal(orders.length, 2);
9	    assert.ok(orders.every((o) => o.user_id === 1));
10	    done();
11	  });
12	});
13	
14	test('totalPaidCents counts only paid orders', (t, done) => {
15	  totalPaidCents((err, total) => {
16	    assert.equal(err, null);
17	    assert.equal(total, 1);
18	    done();
19	  });
20	});
21

1	import { query } from '../db.js';
2	
3	// Callback-style database access. Chapter 5 migrates this to OrderRepository.
4	export function listOrdersForUser(userId, callback) {
5	  query('orders', (o) => o.user_id === userId && o.deleted_at === null, callback);
6	}
7	
8	export function totalPaidCents(callback) {
9	  query('orders', (o) => o.status === 'paid' && o.deleted_at === null, (err, rows) => {
10	    if (err) return callback(err);
11	    callback(null, rows.reduce((sum, o) => sum + o.total_cents, 0));
12	  });
13	}
